module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	// State definitions
	localparam IDLE  = 2'b00;
	localparam LOAD  = 2'b01;
	localparam SHIFT = 2'b10;
	localparam DONE  = 2'b11;

	// Register declarations
	reg [1:0] state, next_state;
	reg [3:0] count;

	// Sequential logic for state transitions and counter
	always @(posedge clk_a or negedge clk_b) begin
		if (!clk_b) begin
			state <= IDLE;
			count <= 4'b0;
	 end else begin
		 state <= next_state;
		 // Update counter based on current state
		 case (state)
			 LOAD: count <= data_in;
			 SHIFT: count <= count - 1;
			 DONE: count <= 4'b0;
			 default: count <= count;
		 endcase
	 end
	end

	// Combinational logic for next state
	always @(*) begin
		next_state = state;
		case (state)
			IDLE: next_state = brstn ? LOAD : IDLE;
			LOAD: next_state = SHIFT;
			SHIFT: next_state = arstn ? DONE : SHIFT;
			DONE: next_state = data_en ? IDLE : DONE;
			default: next_state = IDLE;
		endcase
	end

	// Output the current count
	always @(*) begin
		dataout = count;
	end

endmodule

